target.css:
:root {
  --bg-card: #1a1f3c;
  --bg-stub: #12162b;
  --accent: #f5a623;
  --accent-light: #ffc85e;
  --text-primary: #ffffff;
  --text-secondary: #8b92b8;
  --text-muted: #555e8a;
  --divider: #2e3560;
  --badge-bg: #f5a623;
  --badge-text: #1a1f3c;
  --barcode-color: #2e3560;
  --city-code-color: #ffffff;
  --route-line: #2e3560;
}

.boarding-pass {
  display: flex;
  flex-direction: row;
  width: 520px;
  border-radius: 16px;
  overflow: hidden;
  margin: 20px auto;
  border: 1px solid var(--divider);
}

.pass-main {
  background-color: var(--bg-card);
  flex: 1;
  padding: 20px 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.airline-header {
  display: flex;
  align-items: center;
  gap: 8px;
}

.airline-logo {
  font-size: 18px;
  color: var(--accent);
  transform: rotate(-45deg);
  display: inline-block;
}

.airline-name {
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--text-primary);
  flex: 1;
}

.flight-badge {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1.5px;
  background-color: var(--badge-bg);
  color: var(--badge-text);
  padding: 3px 8px;
  border-radius: 4px;
}

.route-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.city-block {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.city-block--right {
  align-items: flex-end;
}

.city-code {
  font-size: 36px;
  font-weight: 800;
  color: var(--city-code-color);
  line-height: 1;
}

.city-name {
  font-size: 10px;
  color: var(--text-secondary);
  letter-spacing: 0.5px;
}

.route-arrow {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 4px;
}

.dashes {
  flex: 1;
  height: 1px;
  background-color: var(--route-line);
  border-top: 2px dashed var(--text-muted);
}

.plane-icon {
  font-size: 16px;
  color: var(--accent);
}

.info-row {
  display: flex;
  gap: 16px;
  padding-top: 12px;
  border-top: 1px solid var(--divider);
}

.info-item {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.info-label {
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 1px;
  color: var(--text-muted);
}

.info-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
}

.pass-divider {
  width: 20px;
  background-color: var(--bg-stub);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  position: relative;
}

.notch {
  width: 20px;
  height: 20px;
  background-color: #f5f5f5;
  border-radius: 50%;
  position: absolute;
  left: 0;
}

.notch--top {
  top: -10px;
}

.notch--bottom {
  bottom: -10px;
}

.divider-line {
  width: 1px;
  height: 100%;
  border-left: 2px dashed var(--divider);
}

.pass-stub {
  background-color: var(--bg-stub);
  width: 120px;
  padding: 20px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: center;
  justify-content: center;
}

.stub-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.stub-value {
  font-size: 20px;
  font-weight: 800;
  color: var(--accent);
  line-height: 1;
}

.barcode {
  margin-top: 4px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  width: 100%;
}

.barcode-lines {
  width: 80px;
  height: 36px;
  background: repeating-linear-gradient(
    to right,
    var(--text-secondary) 0px,
    var(--text-secondary) 2px,
    transparent 2px,
    transparent 4px,
    var(--text-secondary) 4px,
    var(--text-secondary) 5px,
    transparent 5px,
    transparent 8px
  );
  border-radius: 2px;
}

.barcode-text {
  font-size: 7px;
  letter-spacing: 0.5px;
  color: var(--text-muted);
}
